R["hsg-p3-max-k-sum"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (long long& x : a) in >> x;\n    long long sum = 0;\n    for (int i = 0; i < k; ++i) sum += a[i];\n    long long best = sum;\n    for (int i = k; i < n; ++i) {\n        sum += a[i] - a[i - k];\n        best = max(best, sum);\n    }\n    out << best << \"\\n\";\n}";
W["hsg-p3-max-k-sum"] = "#include <iostream>\n#include <algorithm>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (long long& x : a) in >> x;\n    // near-miss: slides the window but never drops the old element\n    // (sum += a[i] without subtracting a[i-k]) \u2014 the running sum\n    // grows monotonically instead of tracking a fixed window\n    long long sum = 0;\n    for (int i = 0; i < k; ++i) sum += a[i];\n    long long best = sum;\n    for (int i = k; i < n; ++i) {\n        sum += a[i];\n        best = max(best, sum);\n    }\n    out << best << \"\\n\";\n}";
R["hsg-cp-m3-equilibrium"] = "#include <iostream>\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    long long a[200000], total = 0, left = 0;\n    for (int i = 0; i < n; ++i) { in >> a[i]; total += a[i]; }\n    for (int i = 0; i < n; ++i) {\n        long long right = total - left - a[i];\n        if (left == right) { out << i << \"\\n\"; return; }\n        left += a[i];\n    }\n    out << -1 << \"\\n\";\n}";
W["hsg-cp-m3-equilibrium"] = "#include <iostream>\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    long long a[200000], total = 0, left = 0;\n    for (int i = 0; i < n; ++i) { in >> a[i]; total += a[i]; }\n    // near-miss: compares left to total - left (forgets to remove a[i]\n    // from the right side), so the pivot element counts on both sides\n    for (int i = 0; i < n; ++i) {\n        if (left == total - left) { out << i << \"\\n\"; return; }\n        left += a[i];\n    }\n    out << -1 << \"\\n\";\n}";
