R["hsg-p8-grid-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<vector<long long>> P(n + 1, vector<long long>(m + 1, 0));\n    for (int i = 1; i <= n; ++i)\n        for (int j = 1; j <= m; ++j) {\n            long long x; in >> x;\n            P[i][j] = x + P[i-1][j] + P[i][j-1] - P[i-1][j-1];\n        }\n    while (q--) {\n        int r1, c1, r2, c2; in >> r1 >> c1 >> r2 >> c2;\n        out << P[r2][c2] - P[r1-1][c2] - P[r2][c1-1] + P[r1-1][c1-1] << \"\\n\";\n    }\n}\n";
W["hsg-p8-grid-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<vector<long long>> P(n + 1, vector<long long>(m + 1, 0));\n    for (int i = 1; i <= n; ++i)\n        for (int j = 1; j <= m; ++j) {\n            long long x; in >> x;\n            P[i][j] = x + P[i-1][j] + P[i][j-1] - P[i-1][j-1];\n        }\n    while (q--) {\n        int r1, c1, r2, c2; in >> r1 >> c1 >> r2 >> c2;\n        // near-miss: the correction corner is SUBTRACTED, not added back\n        out << P[r2][c2] - P[r1-1][c2] - P[r2][c1-1] - P[r1-1][c1-1] << \"\\n\";\n    }\n}\n";
R["hsg-p8-zero-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    map<long long, long long> cnt;\n    cnt[0] = 1;  // empty prefix: subarrays starting at index 1\n    long long pre = 0, ans = 0;\n    for (int i = 0; i < n; ++i) {\n        pre += a[i];\n        ans += cnt[pre];\n        ++cnt[pre];\n    }\n    out << ans << \"\\n\";\n}\n";
