R["hsg-p8-max-window"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    vector<long long> P(n + 1, 0);\n    for (int i = 1; i <= n; ++i) {\n        long long x; in >> x;\n        P[i] = P[i-1] + x;\n    }\n    long long best = P[k] - P[0];\n    for (int i = 1; i + k <= n; ++i)\n        best = max(best, P[i+k] - P[i]);\n    out << best << \"\\n\";\n}\n";
W["hsg-p8-max-window"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long k; in >> n >> k;\n    vector<long long> P(n + 1, 0);\n    for (int i = 1; i <= n; ++i) {\n        long long x; in >> x;\n        P[i] = P[i-1] + x;\n    }\n    // near-miss: window length k-1 instead of k\n    long long best = P[k-1] - P[0];\n    for (int i = 1; i + k - 1 <= n; ++i)\n        best = max(best, P[i+k-1] - P[i]);\n    out << best << \"\\n\";\n}\n";
R["hsg-cp-m8-split"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    long long total = 0;\n    for (int i = 1; i <= n; ++i) total += a[i];\n    if (total % 3 != 0) { out << 0 << \"\\n\"; return; }\n    long long need = total / 3;\n    vector<long long> P(n + 1, 0);\n    for (int i = 1; i <= n; ++i) P[i] = P[i-1] + a[i];\n    // cnt[i] = number of first-cut positions p <= i with P[p] == need\n    vector<long long> cnt(n + 1, 0);\n    for (int i = 1; i <= n; ++i) cnt[i] = cnt[i-1] + (P[i] == need);\n    long long ans = 0;\n    // second cut j: part 2 non-empty (j >= 2), part 3 non-empty (j <= n-1)\n    for (int j = 2; j <= n - 1; ++j)\n        if (P[j] == 2 * need) ans += cnt[j-1];\n    out << ans << \"\\n\";\n}\n";
W["hsg-cp-m8-split"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <map>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<long long> a(n + 1);\n    for (int i = 1; i <= n; ++i) in >> a[i];\n    long long total = 0;\n    for (int i = 1; i <= n; ++i) total += a[i];\n    if (total % 3 != 0) { out << 0 << \"\\n\"; return; }\n    long long need = total / 3;\n    vector<long long> P(n + 1, 0);\n    for (int i = 1; i <= n; ++i) P[i] = P[i-1] + a[i];\n    vector<long long> cnt(n + 1, 0);\n    for (int i = 1; i <= n; ++i) cnt[i] = cnt[i-1] + (P[i] == need);\n    long long ans = 0;\n    // near-miss: j runs 1..n \u2014 allows an EMPTY first or third part,\n    // which inflates the count on arrays of zeros\n    for (int j = 1; j <= n; ++j)\n        if (P[j] == 2 * need) ans += cnt[j-1];\n    out << ans << \"\\n\";\n}\n";
R["hsg-p9-stamps"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> d(n + 2, 0);\n    for (int i = 0; i < q; ++i) {\n        int l, r; long long v; in >> l >> r >> v;\n        d[l] += v; d[r + 1] -= v;\n    }\n    for (int i = 1; i <= n; ++i) d[i] += d[i-1];\n    for (int i = 1; i <= n; ++i)\n        out << d[i] << (i < n ? \" \" : \"\\n\");\n}\n";
W["hsg-p9-stamps"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<long long> d(n + 2, 0);\n    for (int i = 0; i < q; ++i) {\n        int l, r; long long v; in >> l >> r >> v;\n        // near-miss: stop marker at r instead of r+1 \u2014 every range\n        // loses its last element\n        d[l] += v; d[r] -= v;\n    }\n    for (int i = 1; i <= n; ++i) d[i] += d[i-1];\n    for (int i = 1; i <= n; ++i)\n        out << d[i] << (i < n ? \" \" : \"\\n\");\n}\n";
