R["hsg-p9-posters"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<vector<long long>> D(n + 2, vector<long long>(m + 2, 0));\n    for (int i = 0; i < q; ++i) {\n        int r1, c1, r2, c2; in >> r1 >> c1 >> r2 >> c2;\n        D[r1][c1] += 1; D[r1][c2+1] -= 1;\n        D[r2+1][c1] -= 1; D[r2+1][c2+1] += 1;\n    }\n    long long best = 0;\n    for (int i = 1; i <= n; ++i)\n        for (int j = 1; j <= m; ++j) {\n            D[i][j] += D[i-1][j] + D[i][j-1] - D[i-1][j-1];\n            best = max(best, D[i][j]);\n        }\n    out << best << \"\\n\";\n}\n";
W["hsg-p9-posters"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<vector<long long>> D(n + 2, vector<long long>(m + 2, 0));\n    for (int i = 0; i < q; ++i) {\n        int r1, c1, r2, c2; in >> r1 >> c1 >> r2 >> c2;\n        // near-miss: stop markers at r2/c2 instead of r2+1/c2+1, and\n        // the closing corner shifts accordingly \u2014 every poster shrinks\n        // by one row and one column\n        D[r1][c1] += 1; D[r1][c2] -= 1;\n        D[r2][c1] -= 1; D[r2][c2] += 1;\n    }\n    long long best = 0;\n    for (int i = 1; i <= n; ++i)\n        for (int j = 1; j <= m; ++j) {\n            D[i][j] += D[i-1][j] + D[i][j-1] - D[i-1][j-1];\n            best = max(best, D[i][j]);\n        }\n    out << best << \"\\n\";\n}\n";
