R["hsg-p13-subset"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long t; in >> n >> t;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // meet-in-the-middle lite for n <= 22: enumerate halves\n    vector<long long> L, R;\n    int h = n / 2;\n    for (int mask = 0; mask < (1 << h); ++mask) {\n        long long s = 0;\n        for (int i = 0; i < h; ++i) if (mask >> i & 1) s += a[i];\n        L.push_back(s);\n    }\n    int h2 = n - h;\n    for (int mask = 0; mask < (1 << h2); ++mask) {\n        long long s = 0;\n        for (int i = 0; i < h2; ++i) if (mask >> i & 1) s += a[h + i];\n        R.push_back(s);\n    }\n    sort(R.begin(), R.end());\n    long long ans = 0;\n    for (long long x : L) {\n        auto lo = lower_bound(R.begin(), R.end(), t - x);\n        auto hi = upper_bound(R.begin(), R.end(), t - x);\n        ans += hi - lo;\n    }\n    out << ans << \"\\n\";\n}\n";
W["hsg-p13-subset"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long t; in >> n >> t;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    vector<long long> L, R;\n    int h = n / 2;\n    for (int mask = 0; mask < (1 << h); ++mask) {\n        long long s = 0;\n        for (int i = 0; i < h; ++i) if (mask >> i & 1) s += a[i];\n        L.push_back(s);\n    }\n    int h2 = n - h;\n    for (int mask = 0; mask < (1 << h2); ++mask) {\n        long long s = 0;\n        for (int i = 0; i < h2; ++i) if (mask >> i & 1) s += a[h + i];\n        R.push_back(s);\n    }\n    sort(R.begin(), R.end());\n    long long ans = 0;\n    for (long long x : L) {\n        // near-miss: counts only the FIRST match per x (distance to\n        // lower_bound == 1) instead of every matching element\n        auto lo = lower_bound(R.begin(), R.end(), t - x);\n        if (lo != R.end() && *lo == t - x) ans += 1;\n    }\n    out << ans << \"\\n\";\n}\n";
