R["hsg-p14-rooks"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    // count ways to choose k rows and k columns and match them: C(n,k)^2 * k!\n    long long fact[9]; fact[0] = 1;\n    for (int i = 1; i <= 8; ++i) fact[i] = fact[i-1] * i;\n    // C(n, k) for tiny n\n    long long cnk = fact[n] / (fact[k] * fact[n - k]);\n    out << cnk * cnk * fact[k] << \"\\n\";\n}\n";
W["hsg-p14-rooks"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    long long fact[9]; fact[0] = 1;\n    for (int i = 1; i <= 8; ++i) fact[i] = fact[i-1] * i;\n    long long cnk = fact[n] / (fact[k] * fact[n - k]);\n    // near-miss: forgets the k! matchings between chosen rows and columns\n    out << cnk * cnk << \"\\n\";\n}\n";
R["hsg-cp-m14-paths"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<string> g(n);\n    for (auto& row : g) in >> row;\n    long long cnt = 0;\n    // walk every right/down path\n    struct W { int n, m; vector<string>* g; long long cnt = 0;\n        void go(int r, int c) {\n            if ((*g)[r][c] == '#') return;\n            if (r == n - 1 && c == m - 1) { ++cnt; return; }\n            if (r + 1 < n) go(r + 1, c);\n            if (c + 1 < m) go(r, c + 1);\n        }\n    } w{n, m, &g};\n    w.go(0, 0);\n    out << w.cnt % 1000000007 << \"\\n\";\n}\n";
