R["hsg-p15-coins"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int k, S; in >> k >> S;\n    vector<int> coins(k);\n    for (auto& c : coins) in >> c;\n    const int INF = 1e9;\n    vector<int> dp(S + 1, INF);\n    dp[0] = 0;\n    for (int s = 1; s <= S; ++s)\n        for (int c : coins)\n            if (c <= s && dp[s-c] + 1 < dp[s]) dp[s] = dp[s-c] + 1;\n    out << (dp[S] >= INF ? -1 : dp[S]) << \"\\n\";\n}\n";
