R["hsg-p15-knapsack"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<long long> w(n + 1), v(n + 1);\n    for (int i = 1; i <= n; ++i) in >> w[i] >> v[i];\n    vector<long long> best(W + 1, 0);\n    for (int i = 1; i <= n; ++i)\n        for (int cap = W; cap >= w[i]; --cap)   // descending: each item once\n            best[cap] = max(best[cap], best[cap - w[i]] + v[i]);\n    out << best[W] << \"\\n\";\n}\n";
W["hsg-p15-knapsack"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, W; in >> n >> W;\n    vector<long long> w(n + 1), v(n + 1);\n    for (int i = 1; i <= n; ++i) in >> w[i] >> v[i];\n    vector<long long> best(W + 1, 0);\n    for (int i = 1; i <= n; ++i)\n        for (int cap = w[i]; cap <= W; ++cap)   // near-miss: ASCENDING\n            best[cap] = max(best[cap], best[cap - w[i]] + v[i]);\n    out << best[W] << \"\\n\";\n}\n";
