R["hsg-p16-components"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<char> vis(n + 1, 0);\n    int comps = 0;\n    vector<int> st;\n    for (int s = 1; s <= n; ++s) {\n        if (vis[s]) continue;\n        ++comps;\n        vis[s] = 1; st.push_back(s);\n        while (!st.empty()) {\n            int u = st.back(); st.pop_back();\n            for (int v : adj[u]) if (!vis[v]) { vis[v] = 1; st.push_back(v); }\n        }\n    }\n    out << comps << \"\\n\";\n}\n";
