R["hsg-p16-bfs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<int> dist(n + 1, -1);\n    queue<int> q;\n    dist[s] = 0; q.push(s);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u]) if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }\n    }\n    for (int v = 1; v <= n; ++v)\n        out << dist[v] << (v == n ? \"\" : \" \");\n    out << \"\\n\";\n}\n";
W["hsg-p16-bfs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, s; in >> n >> m >> s;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n        // near-miss: builds a DIRECTED graph \u2014 drops the reverse edge\n    }\n    vector<int> dist(n + 1, -1);\n    queue<int> q;\n    dist[s] = 0; q.push(s);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u])\n            if (dist[v] == -1) { dist[v] = dist[u] + 1; q.push(v); }\n    }\n    for (int v = 1; v <= n; ++v)\n        out << dist[v] << (v == n ? \"\" : \" \");\n    out << \"\\n\";\n}\n";
R["hsg-p16-flood"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<string> g(n);\n    for (auto& row : g) in >> row;\n    int rooms = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j < m; ++j) {\n            if (g[i][j] != '.') continue;\n            ++rooms;\n            vector<pair<int,int>> st{{i, j}};\n            g[i][j] = '#';\n            while (!st.empty()) {\n                auto [r, c] = st.back(); st.pop_back();\n                int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n                for (int d = 0; d < 4; ++d) {\n                    int nr = r + dr[d], nc = c + dc[d];\n                    if (nr >= 0 && nr < n && nc >= 0 && nc < m && g[nr][nc] == '.') {\n                        g[nr][nc] = '#';\n                        st.push_back({nr, nc});\n                    }\n                }\n            }\n        }\n    out << rooms << \"\\n\";\n}\n";
W["hsg-p16-flood"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<string> g(n);\n    for (auto& row : g) in >> row;\n    int rooms = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j < m; ++j) {\n            if (g[i][j] != '.') continue;\n            ++rooms;\n            vector<pair<int,int>> st{{i, j}};\n            g[i][j] = '#';\n            while (!st.empty()) {\n                auto [r, c] = st.back(); st.pop_back();\n                // near-miss: floods only right/down \u2014 misses rooms that bend\n                // around through up/left\n                int dr[] = {1, 0}, dc[] = {0, 1};\n                for (int d = 0; d < 2; ++d) {\n                    int nr = r + dr[d], nc = c + dc[d];\n                    if (nr >= 0 && nr < n && nc >= 0 && nc < m && g[nr][nc] == '.') {\n                        g[nr][nc] = '#';\n                        st.push_back({nr, nc});\n                    }\n                }\n            }\n        }\n    out << rooms << \"\\n\";\n}\n";
R["hsg-p16-grid-dist"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<string> g(n);\n    for (auto& row : g) in >> row;\n    pair<int,int> S{-1, -1}, E{-1, -1};\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j < m; ++j) {\n            if (g[i][j] == 'S') S = {i, j};\n            if (g[i][j] == 'E') E = {i, j};\n        }\n    vector<vector<int>> dist(n, vector<int>(m, -1));\n    queue<pair<int,int>> q;\n    dist[S.first][S.second] = 0;\n    q.push(S);\n    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n    while (!q.empty()) {\n        auto [r, c] = q.front(); q.pop();\n        for (int d = 0; d < 4; ++d) {\n            int nr = r + dr[d], nc = c + dc[d];\n            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;\n            if (g[nr][nc] == '#' || dist[nr][nc] != -1) continue;\n            dist[nr][nc] = dist[r][c] + 1;\n            q.push({nr, nc});\n        }\n    }\n    out << dist[E.first][E.second] << \"\\n\";\n}\n";
W["hsg-p16-grid-dist"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<string> g(n);\n    for (auto& row : g) in >> row;\n    pair<int,int> S{-1, -1}, E{-1, -1};\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j < m; ++j) {\n            if (g[i][j] == 'S') S = {i, j};\n            if (g[i][j] == 'E') E = {i, j};\n        }\n    vector<vector<int>> dist(n, vector<int>(m, -1));\n    queue<pair<int,int>> q;\n    dist[S.first][S.second] = 0;\n    q.push(S);\n    int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};\n    while (!q.empty()) {\n        auto [r, c] = q.front(); q.pop();\n        for (int d = 0; d < 4; ++d) {\n            int nr = r + dr[d], nc = c + dc[d];\n            if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;\n            // near-miss: 'E' is not in the walkable set \u2014 never steps onto it\n            if (g[nr][nc] == '#' || g[nr][nc] == 'E' || dist[nr][nc] != -1) continue;\n            dist[nr][nc] = dist[r][c] + 1;\n            q.push({nr, nc});\n        }\n    }\n    out << dist[E.first][E.second] << \"\\n\";\n}\n";
R["hsg-p16-treecheck"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    if (m != n - 1) { out << \"NO\" << \"\\n\"; return; }\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        if (u == v) { out << \"NO\" << \"\\n\"; return; }  // self-loop: cycle\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<char> vis(n + 1, 0);\n    vector<int> st{1};\n    vis[1] = 1;\n    while (!st.empty()) {\n        int u = st.back(); st.pop_back();\n        for (int v : adj[u]) if (!vis[v]) { vis[v] = 1; st.push_back(v); }\n    }\n    for (int v = 1; v <= n; ++v)\n        if (!vis[v]) { out << \"NO\" << \"\\n\"; return; }\n    out << \"YES\" << \"\\n\";\n}\n";
W["hsg-p16-treecheck"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    if (m != n - 1) { out << \"NO\" << \"\\n\"; return; }\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<char> vis(n + 1, 0);\n    vector<int> st{1};\n    vis[1] = 1;\n    while (!st.empty()) {\n        int u = st.back(); st.pop_back();\n        for (int v : adj[u]) if (!vis[v]) { vis[v] = 1; st.push_back(v); }\n    }\n    // near-miss: assumes m == n-1 already proves a tree \u2014 skips the\n    // connectivity check entirely\n    out << \"YES\" << \"\\n\";\n}\n";
R["hsg-cp-m16-stations"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<int> comp(n + 1, 0);\n    int nextc = 0;\n    vector<int> st;\n    for (int s = 1; s <= n; ++s) {\n        if (comp[s]) continue;\n        ++nextc;\n        comp[s] = nextc; st.push_back(s);\n        while (!st.empty()) {\n            int u = st.back(); st.pop_back();\n            for (int v : adj[u]) if (!comp[v]) { comp[v] = nextc; st.push_back(v); }\n        }\n    }\n    string res;\n    for (int i = 0; i < q; ++i) {\n        int a, b; in >> a >> b;\n        res += (comp[a] == comp[b]) ? \"YES\" : \"NO\";\n        if (i + 1 < q) res += \"\\n\";\n    }\n    out << res << \"\\n\";\n}\n";
W["hsg-cp-m16-stations"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m, q; in >> n >> m >> q;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v); adj[v].push_back(u);\n    }\n    vector<int> comp(n + 1, 0);\n    int nextc = 0;\n    vector<int> st;\n    for (int s = 1; s <= n; ++s) {\n        if (comp[s]) continue;\n        ++nextc;\n        comp[s] = nextc; st.push_back(s);\n        while (!st.empty()) {\n            int u = st.back(); st.pop_back();\n            for (int v : adj[u]) if (!comp[v]) { comp[v] = nextc; st.push_back(v); }\n        }\n    }\n    string res;\n    for (int i = 0; i < q; ++i) {\n        int a, b; in >> a >> b;\n        // near-miss: direct-link check instead of component check \u2014\n        // multi-hop paths report NO\n        bool ok = comp[a] == comp[b];\n        if (a != b) {\n            ok = false;\n            for (int v : adj[a]) if (v == b) { ok = true; break; }\n        }\n        res += ok ? \"YES\" : \"NO\";\n        if (i + 1 < q) res += \"\\n\";\n    }\n    out << res << \"\\n\";\n}\n";
R["hsg-p17-pair-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    int l = 0, r = n - 1;\n    bool ok = false;\n    while (l < r) {\n        long long s = a[l] + a[r];\n        if (s == S) { ok = true; break; }\n        if (s < S) ++l; else --r;\n    }\n    out << (ok ? \"YES\" : \"NO\") << \"\\n\";\n}\n";
W["hsg-p17-pair-sum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    int l = 0, r = n - 1;\n    bool ok = false;\n    while (l < r) {\n        long long s = a[l] + a[r];\n        if (s == S) { ok = true; break; }\n        // near-miss: both pointers move inward each step \u2014 skips the answer\n        ++l; --r;\n    }\n    out << (ok ? \"YES\" : \"NO\") << \"\\n\";\n}\n";
R["hsg-p17-merge"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<long long> a(n), b(m);\n    for (auto& x : a) in >> x;\n    for (auto& x : b) in >> x;\n    long long cnt = 0;\n    int j = 0;\n    for (int i = 0; i < n; ++i) {\n        while (j < m && b[j] < a[i]) ++j;   // j only moves forward\n        cnt += j;\n    }\n    out << cnt << \"\\n\";\n}\n";
W["hsg-p17-merge"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, m; in >> n >> m;\n    vector<long long> a(n), b(m);\n    for (auto& x : a) in >> x;\n    for (auto& x : b) in >> x;\n    long long cnt = 0;\n    // near-miss: counts A[i] >= B[j] \u2014 equal pairs wrongly included\n    int j = 0;\n    for (int i = 0; i < n; ++i) {\n        while (j < m && b[j] <= a[i]) ++j;\n        cnt += j;\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsg-p17-distinct"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    vector<int> cnt(1000001, 0);\n    int l = 0, best = 0;\n    for (int r = 0; r < n; ++r) {\n        ++cnt[a[r]];\n        while (cnt[a[r]] > 1) --cnt[a[l++]];   // restore all-distinct\n        best = max(best, r - l + 1);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsg-p17-distinct"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    vector<int> cnt(1000001, 0);\n    int l = 0, best = 0;\n    for (int r = 0; r < n; ++r) {\n        ++cnt[a[r]];\n        // near-miss: records the window BEFORE restoring all-distinctness \u2014\n        // invalid windows inflate the answer\n        best = max(best, r - l + 1);\n        while (cnt[a[r]] > 1) --cnt[a[l++]];\n    }\n    out << best << \"\\n\";\n}\n";
R["hsg-p17-subsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long sum = 0;\n    int l = 0, best = n + 1;\n    for (int r = 0; r < n; ++r) {\n        sum += a[r];\n        while (sum - a[l] >= S && l <= r) { sum -= a[l]; ++l; }\n        if (sum >= S) best = min(best, r - l + 1);\n    }\n    out << (best > n ? -1 : best) << \"\\n\";\n}\n";
W["hsg-p17-subsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long sum = 0;\n    int l = 0, best = n + 1;\n    for (int r = 0; r < n; ++r) {\n        sum += a[r];\n        if (sum >= S) best = min(best, r - l + 1);\n        // near-miss: shrinks only when sum >= S + a[l] \u2014 leaves fat windows\n        while (sum >= S && sum - a[l] >= 0 && l <= r) { sum -= a[l]; ++l; }\n    }\n    out << (best > n ? -1 : best) << \"\\n\";\n}\n";
R["hsg-p17-ksum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long sum = 0;\n    for (int i = 0; i < k; ++i) sum += a[i];\n    long long best = sum;\n    for (int r = k; r < n; ++r) {\n        sum += a[r] - a[r - k];\n        best = max(best, sum);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsg-p17-ksum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long sum = 0;\n    for (int i = 0; i < k; ++i) sum += a[i];\n    long long best = sum;\n    for (int r = k; r < n; ++r) {\n        // near-miss: adds the new element but forgets to drop the old one\n        sum += a[r];\n        best = max(best, sum);\n    }\n    out << best << \"\\n\";\n}\n";
R["hsg-cp-m17-toys"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, k; in >> n >> k;\n    vector<int> t(n);\n    for (auto& x : t) in >> x;\n    vector<int> cnt(101, 0);\n    int distinct = 0, l = 0, best = 0;\n    for (int r = 0; r < n; ++r) {\n        if (cnt[t[r]]++ == 0) ++distinct;\n        while (distinct > k)\n            if (--cnt[t[l++]] == 0) --distinct;\n        best = max(best, r - l + 1);\n    }\n    out << best << \"\\n\";\n}\n";
