R["hsg-p18-budget"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long N, TL; in >> N >> TL;\n    long long budget = 50000000LL * TL;\n    if (N <= 25) { out << \"exponential\" << \"\\n\"; return; }\n    if (N <= 1000 && N * N * N <= budget) { out << \"cubic\" << \"\\n\"; return; }\n    if (N * N <= budget) { out << \"quadratic\" << \"\\n\"; return; }\n    long long logn = 0; long long t = N;\n    while (t > 1) { t /= 2; ++logn; }\n    if (N * logn <= budget) { out << \"linearithmic\" << \"\\n\"; return; }\n    out << \"linear\" << \"\\n\";\n}\n";
W["hsg-p18-budget"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    long long N, TL; in >> N >> TL;\n    long long budget = 50000000LL * TL;\n    if (N <= 25) { out << \"exponential\" << \"\\n\"; return; }\n    if (N <= 1000 && N * N * N <= budget) { out << \"cubic\" << \"\\n\"; return; }\n    // near-miss: quadratic test uses N^2 * TL instead of N^2 <= budget \u2014\n    // double-counts the time limit\n    if (N * N <= budget * TL) { out << \"quadratic\" << \"\\n\"; return; }\n    long long logn = 0; long long t = N;\n    while (t > 1) { t /= 2; ++logn; }\n    if (N * logn <= budget) { out << \"linearithmic\" << \"\\n\"; return; }\n    out << \"linear\" << \"\\n\";\n}\n";
