W["hsg-p18-bruteforce"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; long long S; in >> n >> S;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long cnt = 0;\n    // near-miss: counts ordered triples (i,j,k) and (k,j,i) alike \u2014\n    // does not enforce i < j < k\n    for (int i = 0; i < n; ++i)\n        for (int j = 0; j < n; ++j)\n            for (int k = 0; k < n; ++k)\n                if (i != j && j != k && i != k && a[i] + a[j] + a[k] == S) ++cnt;\n    out << cnt << \"\\n\";\n}\n";
